// ================= TITLE =================
C.push(['title', 'Guideline-Anchored Monotone Additive Modelling with Certified Narratives, Exact Counterfactuals and Subgroup-Conditional Conformal Screening for Ten-Year Coronary Heart Disease Risk Prediction']);
C.push(['author', 'Niranjan L¹*, Chaithra K R²']);
C.push(['affil', '¹ Department of Computer Science and Engineering (AI&ML), Nagarjuna College of Engineering and Technology, Bengaluru, Karnataka, India (affiliated to VTU, Belagavi)']);
